// The Error Trigger hands us the failed execution and its workflow. Capture enough
// to reproduce the failure without needing the n8n UI to understand it.
const e = $input.first().json ?? {};
const execution = e.execution ?? {};
const workflow = e.workflow ?? {};
const err = execution.error ?? {};

// Best-effort: the failing item often carries the lead it was working on.
const failedItem = err.item ?? execution.data?.resultData?.lastNodeExecuted ?? null;
const leadId = err.lead_id ?? e.lead_id ?? null;

return [{ json: {
  workflow: workflow.name ?? 'unknown',
  execution_id: String(execution.id ?? ''),
  lead_id: leadId,
  // Deliberately null: an unhandled crash has no effect we can name, so it gets no
  // idempotency key and is always recorded rather than deduped away.
  idempotency_key: null,
  payload: {
    last_node: execution.lastNodeExecuted ?? null,
    mode: execution.mode ?? null,
    retry_of: execution.retryOf ?? null,
    execution_url: execution.url ?? null,
    failed_item: failedItem,
  },
  error: {
    message: err.message ?? String(err),
    name: err.name ?? null,
    node: err.node?.name ?? execution.lastNodeExecuted ?? null,
    stack: typeof err.stack === 'string' ? err.stack.split('\n').slice(0, 5).join('\n') : null,
  },
} }];
